/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const p = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json','utf8'));
const c = JSON.parse(fs.readFileSync('.exp_agent/round_01/completion.json','utf8'));
const errors = [];
for (const key of ['selected_rules','entity_repairs','blocked','unresolved_external']) if ("'!(key in c)) errors.push(`missing ${key}`);
if (JSON.stringify(c.selected_rules) !== JSON.stringify(p.rules.map(r => r.rule))) errors.push('"'selected_rules mismatch');
if ("'!Array.isArray(c.blocked) || c.blocked.length) errors.push('"'blocked nonempty');
if ("'!Array.isArray(c.unresolved_external) || c.unresolved_external.length) errors.push('"'unresolved_external nonempty');
for (const [i,e] of c.entity_repairs.entries()) {
  for (const key of ['rule','relative_path','locations','entities','evidence','transformation','status']) if ("'!(key in e)) errors.push(`repair ${i} missing ${key}`);
  if (!Array.isArray(e.locations) || e.locations.length < 1) errors.push(`repair ${i} locations`);
  if (!Array.isArray(e.entities) || e.entities.length < 1 || e.entities.some(x => typeof x !== '"'string' || "'!x)) errors.push(`repair ${i} entities`);
  if (!Array.isArray(e.evidence) || e.evidence.length < 1 || e.evidence.some(x => typeof x !== '"'string' || "'!x)) errors.push(`repair ${i} evidence`);
  if (e.status !== '"'repaired' || typeof e.transformation "'!== '"'string' || "'!e.transformation) errors.push(`repair ${i} status/transformation`);
}
console.log(JSON.stringify({valid: errors.length === 0, errors, repairs:c.entity_repairs.length, locations:c.entity_repairs.reduce((n,e)=>n+e.locations.length,0)}, null, 2));
NODE'

/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const p = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json','utf8'));
const c = JSON.parse(fs.readFileSync('.exp_agent/round_01/completion.json','utf8'));
const key = x => "'`${x.rule}|${x.relative_path}|${x.line}|${x.column}`;
const expected = p.rules.flatMap(r => r.files.flatMap(f => f.locations.map(l => key({rule:r.rule,relative_path:f.relative_path,...l})))).sort();
const actual = c.entity_repairs.flatMap(e => e.locations.map(l => key({rule:e.rule,relative_path:e.relative_path,...l}))).sort();
console.log(JSON.stringify({exact:JSON.stringify(expected)===JSON.stringify(actual), expected:expected.length, actual:actual.length, duplicate_actual:actual.length-new Set(actual).size}, null, 2));
